window.RP_SESSION={"id":"S-4a6010a03e55","messages":[{"id":"RP-II-0112305","time":"2026-07-01T15:07:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"비내리는~\n  거리에서~\n\n🌧 온 종일~\n널 생각...\n\n안녕하세요? 셔먼 혹스입니다.","characters":[]},{"id":"RP-II-0112306","time":"2026-07-01T15:09:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"❓️","characters":[]},{"id":"RP-II-0112307","time":"2026-07-01T15:09:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"wait a minute..","characters":[]},{"id":"RP-II-0112308","time":"2026-07-01T15:09:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"whos that shit!??","characters":[]},{"id":"RP-II-0112309","time":"2026-07-01T15:10:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"압니다. 알아요.\n\n셔먼 혹스? 그게 누구야?\n\n새로운 길드원인가? 싶어 명단을 뒤적이는 여러분의 모습이 눈에 훤하네요.\n\n셔먼 혹스? 어디서 나왔더라... 하며 검색중인 션님의 재빠른 손가락도 보입니다.","characters":[]},{"id":"RP-II-0112310","time":"2026-07-01T15:14:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"명단에도 없어...\n검색해도 안나와...","characters":[]},{"id":"RP-II-0112311","time":"2026-07-01T15:15:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그럼 대체... 저 셔먼 혹스가 누구냐구요?","characters":[]},{"id":"RP-II-0112312","time":"2026-07-01T15:17:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"https://youtu.be/ddon3hc2MrE?si=CG11LM6Mkyd0vKMB","characters":[]},{"id":"RP-II-0112313","time":"2026-07-01T15:17:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"내 이름은 셔먼 혹스.\n탐정이죠...!","characters":[]},{"id":"RP-II-0112314","time":"2026-07-01T15:36:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"케케묵은 사건을 해결하는 뒷골목의 해결사이자, 사라진 아이들, 물건들, 마당의 똥개, 씨암탉까지 수소문하야 찾아내는 만능 탐정...!","characters":[]},{"id":"RP-II-0112315","time":"2026-07-01T15:44:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"오늘의 미해결 사건은 뭘까요?","characters":[]},{"id":"RP-II-0112316","time":"2026-07-01T15:45:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"돌림판 게임 시작! 지금 바로 돌림판을 돌려보고 결과를 확인해 주세요.","characters":[]},{"id":"RP-II-0112317","time":"2026-07-01T15:46:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진\n메시지가 삭제되었습니다.","characters":[]},{"id":"RP-II-0112318","time":"2026-07-01T15:46:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"와..자...잣...!!!","characters":[]},{"id":"RP-II-0112319","time":"2026-07-01T16:02:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"외..도 증거수집.\n\n좋습니다.","characters":[]},{"id":"RP-II-0112320","time":"2026-07-01T16:02:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"이렇게 시작해봅시다.\n\n시작은...","characters":[]},{"id":"RP-II-0112321","time":"2026-07-01T16:02:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"남편의... 외도를 의심하기 시작한...","characters":[]},{"id":"RP-II-0112322","time":"2026-07-01T16:05:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"메누인 부인의 요청에서부터였습니다.\n메누인 부인의 남편은...","characters":[]},{"id":"RP-II-0112323","time":"2026-07-01T16:06:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"돌림판 게임 시작! 지금 바로 돌림판을 돌려보고 결과를 확인해 주세요.","characters":[]},{"id":"RP-II-0112324","time":"2026-07-01T16:06:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"돌림판 게임 결과는 유명한 양아치였다 입니다.","characters":[]},{"id":"RP-II-0112325","time":"2026-07-01T16:06:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-II-0112326","time":"2026-07-01T16:07:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"도시에서 유명한 양아치였죠.","characters":[]},{"id":"RP-II-0112328","time":"2026-07-01T16:30:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"양아치에 외도라니, 뻔한 난봉꾼이잖아요? 하실 수도 있겠으나.\n\n메누인 부인의 사정을 들어보니 눈물이 쏙 빠지는 일이었습니다.\n\n한 때 용병으로 일하던 남편은 전선에서 외팔이가 되어 돌아왔댑니다.\n\n낙심 때문인지, 부모에게 물려받은 밭도 노름으로 날려먹고 놈팽이 한량처럼 지냈답죠.\n\n외도도 이번이 처음은 아니랍디다.\n\n부인의 말을 들어보시죠.\n\n\" 그 양반이, 아니 그 놈팽이 자식이 치마폭 여럿 들추고 다니는거야 익숙하죠! 아니 치마 밑으로만 기어들어갔으면 그마저도 다행입디다. 그런데 탐정 나으리, 애 좀 보세요. 애가 고작 두 살 배기에, 젖도 이제 막 떼기 시작했는데 일은 커녕 이젠 솥가마니도 바닥을 보이는데 외간 여자한테 쏟아붓기 일쑤래두요!? 내가, 내가 여간 서러워서요. 차라리 어디가서 콱 죽기라도 하지! 콱 죽어 돌아오지라도 말지요! 탐정 나으리, 내가요! 내가! \"","characters":[]},{"id":"RP-II-0112329","time":"2026-07-01T16:33:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그렇게 생각하고 있었는데. 집에 안돌아온지 벌써 닷새쨉니다. 차라리 주검으로라도 돌아오지. 어디서, 언 년이랑 붙어먹는지라도 알면 내 그 쪽으로 침이라도 뱉지요. 저 어린 아가 호로자식으로 자랄바엔... 욕짓거릴 들어도 살아나있지요. 그렇게라도 하시지! 어흐흑... \"\n\n이~런 천하의 쓸모 반 푼 어치도 없는 놈.\n\n때문에 나 셔먼 혹스는 결심한겁니다.\n\n네 이놈. 기필코 찾아내 눈물콧물 쏙 빼주겠노라고 말입니다.","characters":[]},{"id":"RP-II-0112330","time":"2026-07-01T16:34:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"맡겨주시라! 이 몸 출두, 셔먼 혹스!","characters":[]},{"id":"RP-II-0112331","time":"2026-07-01T16:34:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-II-0112332","time":"2026-07-01T16:35:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그리하야 밝혀낸 첫번째 증-거!!","characters":[]},{"id":"RP-II-0112333","time":"2026-07-01T16:36:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"!운명","characters":[]},{"id":"RP-II-0112334","time":"2026-07-01T16:36:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 3 = 3\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0112335","time":"2026-07-01T16:36:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"드르렁~","characters":[]},{"id":"RP-II-0112336","time":"2026-07-01T16:36:00+09:00","room":"RP II","name":"셔먼 혹스 / 메누인 부인","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0112337","time":"2026-07-01T16:36:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
